%[text] ## Advanded manipulation
%[text] Take a complexe valued phasor array, you can extract the real part of A(t) and imag part of A(t), conjugate phasor, and transpose conjugate phasor with '
X = rand_phasor(2,2,5,"time_structure","cmplx",output="PhasorArray") %[output:732644cc]
figure %[output:0f93178b]
plot(X,1,0:0.01:2,"DispImag",1,"DispReal",1) %[output:0f93178b]

rX=mreal(X) %[output:10b210df]
figure %[output:19ff4be9]
plot(rX,1,0:0.01:2,"DispImag",1,"DispReal",1) %[output:19ff4be9]

iX=mimag(X)*1i %[output:90b99e07]
figure %[output:0bee29f2]
plot(iX,1,0:0.01:2,"DispImag",1,"DispReal",1) %[output:0bee29f2]

cX=mconj(X) %[output:27ee078b]
figure %[output:7b6368f5]
plot(cX,1,0:0.01:2,"DispImag",1,"DispReal",1) %[output:7b6368f5]

tcX=X' %[output:5fde96d0]
figure %[output:361b95be]
plot(tcX,1,0:0.01:2,"DispImag",1,"DispReal",1) %[output:361b95be]


