%[text] ## More...

% Fourier Forms compatible with respective toeplitz formalism
A.F_bt %[output:32b6c9cf]
A.F_tb  %[output:1938562f]


% Vectorized fourier
A.FvTB(5) %[output:35f5629a]
A{:}.F_tb(5) %[output:492a8794]

%TB2Array retrieve the underlying phasor array, knowing at least one
%dimension of the time domain matrices, other dimension are automatically
%deduced
TB2array(A.T_tb(h),size(A,1))  %[output:9d48a4fd]


sum(A,1) %[output:744ef559]
permute(A,[2 1]) %[output:63fb929b]
size(A,1) %[output:647c56b8]
size(A,2) %[output:8cc7797b]
numel(A) %[output:085ab31c]
numelt(A) %[output:85c4f36f]

angle=1.57 %rad %[output:5a353156]
evalp(A,angle) %[output:5b2482c8]

B=rand_phasor(3,1,7,'output','PhasorArray') %[output:26b5cf0e]
iscolumn(B) %[output:1be97d79]
isrow(B) %[output:928528c8]
isrow(B.') %[output:9d53fa74]
ismatrix(B) %[output:7d14888c]
issquare(B) %[output:1002469a]

C=rand_phasor(1,1,8,'output','PhasorArray') %[output:2de39c4b]
isscalar(C) %[output:1180b0fc]

issquare(A) %[output:0bba92a7]

figure %[output:7291586d]
plot(A) %[output:7291586d]
figure %[output:84f3e5fa]
plot(retro(A)) %[output:84f3e5fa]

